import '../../test/deterministic.environment.ts';
import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';
import { randomBytes, randomUUID } from 'node:crypto';
import { ProcessingGrantCodec } from '../../apps/backend/src/admission/processing.grant.ts';
import { ProcessingAdmission } from '../../apps/backend/src/admission/processing.admission.ts';
import { OutputDelivery } from '../../apps/backend/src/media/output-delivery.ts';
import { Writable } from 'node:stream';

// Only isolated domain objects and injected fake ports. No app composition,
// configuration/credential/media reads, network, listener, provider, or native tool.
globalThis.fetch = async () => { throw new Error('audit-network-prohibited'); };
let now = 1_000_000, checks = 0, dispatches = 0;
const policy = {ttlMs:7_200_000,maxRecords:256,maxConcurrent:1,maxDispatches:1,rateWindowMs:300_000,maxGrantsPerWindow:3,allowedOrigins:['http://localhost:3000'],paidEnabled:true,timeoutMs:1000};
function fresh() {
  const codec = new ProcessingGrantCodec({v1:randomBytes(32).toString('base64url')},'v1',randomUUID(),()=>now,policy.ttlMs);
  return new ProcessingAdmission(codec,policy,{verify:async()=>{checks++;return true;}},()=>now,randomBytes(32));
}
const admission=fresh();
for(let i=0;i<3;i++) admission.issue('http://localhost:3000','same-origin');
assert.throws(()=>admission.issue('http://localhost:3000','same-origin'),error=>error.code==='RATE_LIMITED');
assert.equal(checks,0);
const grants= {issuedBeforeBotCheck:3,nextVisitor:'RATE_LIMITED',verifierCalls:checks};
now+=300_001;
const issued=admission.issue('http://localhost:3000','same-origin');
const context={cookie:issued.cookie,origin:'http://localhost:3000',fetchSite:'same-origin',csrf:issued.grant.csrf,signal:new AbortController().signal};
const action={bytes:Buffer.from('{}'),contentType:'application/json',allowedContentTypes:['application/json'],maxBytes:2,turnstileToken:'synthetic-only',action:'transcription' as const};
await admission.run(context,action,()=>{},async()=>{dispatches++;return {};});
const next=admission.issue('http://localhost:3000','same-origin');
await assert.rejects(admission.run({...context,cookie:next.cookie,csrf:next.grant.csrf},action,()=>{},async()=>{dispatches++;return {};}),error=>error.code==='PROVIDER_BUDGET_EXHAUSTED');
const second=fresh();
assert.throws(()=>second.session(context),error=>error.code==='SESSION_INVALID');
const rebootGrant=second.issue('http://localhost:3000','same-origin');
await second.run({...context,cookie:rebootGrant.cookie,csrf:rebootGrant.grant.csrf},action,()=>{},async()=>{dispatches++;return {};});
assert.equal(dispatches,2);
const restart={configuredDispatchesPerProcess:1,isolatedProcesses:2,allowedFakeDispatches:dispatches,oldGrantRejected:true};

let reads=0;
const binding={sessionId:issued.grant.sessionId,sourceRevision:`rev_${'a'.repeat(22)}`,fingerprint:'a'.repeat(64)};
const output={artifactId:randomUUID(),generation:'1',bytes:4,checksum:'a'.repeat(64)};
const descriptor={binding,manifestHash:'b'.repeat(64),output,expiresAtMs:now+600_000};
const delivery=new OutputDelivery({restoreSession:()=>issued.grant} as never,{verify:()=>descriptor} as never,{
  outputInfo:async()=>descriptor,
  outputContent:async()=>{reads++;return new Response(new Uint8Array(4),{headers:{'content-type':'video/mp4','content-length':'4'}});}
},()=>now);
await delivery.open(context,{});
for(let i=0;i<30;i++) await delivery.stream(context,undefined,new Writable({write(_chunk,_encoding,done){done();}}),()=>{});
assert.equal(reads,30);
const repeatDelivery={sequentialFakeReads:reads,processingDispatchesAdded:0,cumulativeFakeBytes:reads*4};
const results={date:new Date().toISOString(),mode:'isolated synthetic ports; fake/paid-off process environment',grants,restart,repeatDelivery};
await writeFile('tmp/stride-audit-20261007/proofs.json',JSON.stringify(results,null,2));
console.log(JSON.stringify(results,null,2));

