import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const lock = readFileSync('pnpm-lock.yaml', 'utf8');
const section = lock.split(/^packages:\s*$/m)[1].split(/^snapshots:\s*$/m)[0];
const pairs = [...section.matchAll(/^  (?:"([^"]+)"|'([^']+)'|([^\s][^:]*)):\s*$/gm)].map(m => {
  const key = m[1] ?? m[2] ?? m[3];
  const at = key.lastIndexOf('@');
  return {name:key.slice(0,at),version:key.slice(at+1)};
});
const bulk = {};
for (const p of pairs) (bulk[p.name] ??= []).push(p.version);
const output = {startedAt:new Date().toISOString(),lockSha256:createHash('sha256').update(lock).digest('hex'),packageVersions:pairs.length,packageNames:Object.keys(bulk).length,pairs};
for (const [name,url,body] of [
  ['npm','https://registry.npmjs.org/-/npm/v1/security/advisories/bulk',bulk],
  ['osv','https://api.osv.dev/v1/querybatch',{queries:pairs.map(p=>({package:{name:p.name,ecosystem:'npm'},version:p.version}))}]
]) {
  try {
    const response=await fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body),redirect:'error',signal:AbortSignal.timeout(60000)});
    output[name]={url,status:response.status,body:await response.json(),checkedAt:new Date().toISOString()};
  } catch(error) {output[name]={url,error:error.code??error.name};}
}
writeFileSync('tmp/stride-audit-20261007/dependency-feed.json',JSON.stringify(output,null,2));
console.log(JSON.stringify({packageVersions:output.packageVersions,packageNames:output.packageNames,npmStatus:output.npm?.status,npmPackages:Object.keys(output.npm?.body??{}),osvStatus:output.osv?.status,osvMatches:output.osv?.body?.results?.flatMap((r,i)=>r.vulns?.length?[{...pairs[i],ids:r.vulns.map(v=>v.id)}]:[])??[],errors:[output.npm?.error,output.osv?.error].filter(Boolean)},null,2));
